package com.ecole.gestion_scolaire.student.controller;
import com.ecole.gestion_scolaire.student.dto.*; import com.ecole.gestion_scolaire.student.service.StudentGuardianService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/student-guardians") public class StudentGuardianController{private final StudentGuardianService service;public StudentGuardianController(StudentGuardianService s){service=s;} @GetMapping("/student/{studentId}") @PreAuthorize("hasAuthority('LIEN_RESPONSABLE_CONSULTER')") public List<StudentGuardianResponse> byStudent(@PathVariable Long studentId){return service.findByStudent(studentId);} @PostMapping("/student/{studentId}") @PreAuthorize("hasAuthority('LIEN_RESPONSABLE_GERER')") public ResponseEntity<StudentGuardianResponse> create(@PathVariable Long studentId,@Valid @RequestBody StudentGuardianRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(studentId,r));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('LIEN_RESPONSABLE_GERER')") public StudentGuardianResponse update(@PathVariable Long id,@Valid @RequestBody StudentGuardianRequest r){return service.update(id,r);}}
